def true_acc(p):
    z = -0.2 + sum(EFF[k][p[i]] for i, k in enumerate(names))
    if p[1] == 2 and p[3] > 0: z -= 0.45           # «una palabra» choca con razonar
    if p[2] == 3 and p[3] == 2: z -= 0.15           # demasiado largo
    return 1 / (1 + np.exp(-z)) * 0.95
