def tiempos(F, M, a0):
    t_f, t_c = [], []
    for i in range(NM):
        last = -a0[i]
        for d in range(len(F)):
            if F[d, i]: t_f.append(d + 1 - last); last = d + 1
            elif M[d, i]: t_c.append(d - last); last = d
    return t_f, t_c
